head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > groupby]<br/>Body Column 을 기준으로 데이터를 그룹핑하여 Group Header/Footer 함께 표시합니다.",
    "validation" : [
        "groupbyHeader.expression(선택) 파라미터로 inputType 이 'expression' 일때 Group Header Column 의 표시 형식을 자유롭게 설정할 수 있어야 합니다.",
        "groupbyHeader.expression(선택) 파라미터로 텍스트와 내부 메소드를 사용하여 자유로운 표현이 가능해야 합니다.",
        "expression 내부 메소드 sum(colID) 는 그룹 내 해당 Column 값의 합계를 계산해야 합니다.",
        "expression 내부 메소드 avg(colID) 는 그룹 내 해당 Column 값의 평균을 계산해야 합니다.",
        "expression 내부 메소드 max(colID) 는 그룹 내 해당 Column 값의 최대값을 반환해야 합니다.",
        "expression 내부 메소드 min(colID) 는 그룹 내 해당 Column 값의 최소값을 반환해야 합니다.",
        "expression 내부 메소드 count() 는 그룹 내 Row 수를 반환해야 합니다.",
        "expression 내부 메소드 toggle() 는 그룹 Depth 에 맞게 들여쓰기가 적용된 Group 토글 버튼을 표시해야 합니다.",
        "expression 내부 메소드 depth() 는 현재 그룹의 Depth 를 숫자로 반환해야 합니다.",
        "expression 내부 메소드 depthStr() 는 현재 Depth 의 그룹 기준이 되는 데이터값을 showOnlyLastDepth 파라미터값에 맞게 반환해야 합니다.",
        "showOnlyLastDepth(선택) true 설정 시, depthStr() 내부 메소드 실행 시 현재 Depth 의 그룹 기준이 되는 데이터값만 표시해야 합니다.",
        "showOnlyLastDepth(선택) false 설정 시, depthStr() 내부 메소드 실행 시 현재 Depth 의 그룹을 포함하여 상위 그룹의 데이터값을 ' - ' 문자를 구분자로 모두 표시해야 합니다.",
        "showOnlyLastDepth(선택) 미설정 시, 기본값 false 로 동작하여 현재 Depth 의 그룹을 포함하여 상위 그룹의 데이터값을 ' - ' 문자를 구분자로 모두 표시해야 합니다.",
    ]
}



// 알려진 데이터셋 기준 그룹별 기대 계산값 (_1/_2 와 동일한 한글 4컬럼 데이터 사용)
//  sortIndex [0,1] (region=지역, dept=부서) 오름차순 -> DOM Group Header 표시(화면) 순서:
//  [0] 부산(d0) / [1] 부산-기획(d1) / [2] 부산-영업(d1) / [3] 서울(d0) / [4] 서울-개발(d1) / [5] 서울-영업(d1)
//  집계 대상 숫자 컬럼 = score. 부산: 기획60/영업50, 서울: 개발20·10·30/영업40 (avg 전부 정수로 확정)
scwin.expectedArr = [
    { name: "부산",      depth: 0, sum: 110, avg: 55, max: 60, min: 50, count: 2, full: "부산",        last: "부산" },
    { name: "부산-기획", depth: 1, sum: 60,  avg: 60, max: 60, min: 60, count: 1, full: "부산 - 기획", last: "기획" },
    { name: "부산-영업", depth: 1, sum: 50,  avg: 50, max: 50, min: 50, count: 1, full: "부산 - 영업", last: "영업" },
    { name: "서울",      depth: 0, sum: 100, avg: 25, max: 40, min: 10, count: 4, full: "서울",        last: "서울" },
    { name: "서울-개발", depth: 1, sum: 60,  avg: 20, max: 30, min: 10, count: 3, full: "서울 - 개발", last: "개발" },
    { name: "서울-영업", depth: 1, sum: 40,  avg: 40, max: 40, min: 40, count: 1, full: "서울 - 영업", last: "영업" }
];

// 선택 메소드 -> groupbyHeader expression 문자열 조립
//  sum/avg/max/min : colID 인자 필요(숫자 컬럼 'score') / count/depth/depthStr/toggle : 인자 없음
scwin.buildExpression = function (method) {
    switch (method) {
        case 'sum':      return "sum('score')";
        case 'avg':      return "avg('score')";
        case 'max':      return "max('score')";
        case 'min':      return "min('score')";
        case 'count':    return "count()";
        case 'depth':    return "depth()";
        case 'depthStr': return "depthStr()";
        case 'toggle':   return "toggle()";
        default:         return "";
    }
};



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 초기값 명시 (초기 selectedIndex 미적용 대비)
    par_method.setValue("sum");            // 최초 선택 메소드 = sum
    con_showOnlyLastDepth.setValue("1");   // 미설정('1') -> depthStr 기본(false) 동작

    // comp 초기 생성 (초기 par_method 로 groupby 적용)
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : 지역(region)/부서(dept) 그룹 기준 + score(집계 대상) 포함 4컬럼 구성 후 초기 groupby 적용
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 지역(region)/부서(dept) 2개 컬럼 기준 groupby (sortIndex [0,1], 오름차순). score(점수) 는 집계 대상 숫자 컬럼. (_1/_2 와 동일한 한글 4컬럼 데이터)\n데이터: 부산-기획(60)/부산-영업(50), 서울-개발(20·10·30)/서울-영업(40).\nGroup Header 배치(B): 앞 3칸(지역/부서/등급 병합)=toggle()+depthStr() 그룹명, 점수 칸=선택 메소드 결과.\n[절차] par_method 셀렉트박스에서 내부 메소드(sum/avg/max/min/count/depth/depthStr/toggle) 선택 -> (선택 메소드 expression 적용) 클릭 -> 선택 메소드가 점수 칸(둘째 셀)에 표시.\ndepthStr 검증 시 con_showOnlyLastDepth 변경 후 재적용.\n[확인] 점수 칸(둘째 셀) 실측값을 기대 계산값과 대비(화면순서). sum/avg/max/min/count : 부산(d0)=110/55/60/50/2, 서울(d0)=100/25/40/10/4, 서울-개발(d1)=60/20/30/10/3. depth()=Depth 숫자(d0/d1). depthStr()=그룹명(showOnlyLastDepth=true 면 현재 Depth 만, false/미설정 이면 상위 Depth 포함 스페이스하이픈스페이스 구분). toggle()=w2grid_plus/minus 아이콘, 들여쓰기 margin-left=depth*20px(텍스트 아님)."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="grade" dataType="text"></w2:column>';
    strDlt += '<w2:column id="score" name="score" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // _1/_2 와 동일한 한글 4컬럼 데이터 (그룹별 score 합/평균/최대/최소/개수가 딱 떨어지도록 구성)
    //  부산: 기획60/영업50, 서울: 개발20·10·30/영업40
    let jsonData = [
        { "region": "부산", "dept": "기획", "grade": "C", "score": 60 },
        { "region": "서울", "dept": "개발", "grade": "A", "score": 20 },
        { "region": "서울", "dept": "영업", "grade": "B", "score": 40 },
        { "region": "부산", "dept": "영업", "grade": "B", "score": 50 },
        { "region": "서울", "dept": "개발", "grade": "A", "score": 10 },
        { "region": "서울", "dept": "개발", "grade": "A", "score": 30 }
    ];
    dlt_bind.setJSON(jsonData, false);

    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (_1/_2 와 동일한 지역/부서/등급/점수 4컬럼). height 700px -> 전 그룹(Group Header/데이터) 렌더
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:600px;height:700px;">';
    strTarget += '<w2:caption style="" id="caption1" value="groupby expression 내부메소드 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="100" inputType="text" id="hcol1" value="지역(0)"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="hcol2" value="부서(1)"></w2:column>';
    strTarget += '<w2:column width="80" inputType="text" id="hcol3" value="등급(2)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="점수(3)"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    //  (중요) body 컬럼 id 는 dataList 컬럼 id 와 동일해야 셀에 데이터가 바인딩됨
    strTarget += '<w2:column width="100" inputType="text" dataType="text" id="region" dataList="region"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" dataType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="80" inputType="text" dataType="text" id="grade" dataList="grade"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" dataType="number" displayFormat="#,###" id="score" dataList="score" align="right"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 초기 groupby 적용 (현재 par_method 선택값 기준)
    scwin.applyGroupby(par_method.getValue(), con_showOnlyLastDepth.getText());
}



// groupbyHeader 를 실사용(SubTotal) 배치로 구성하여 groupby 적용 (B 방식)
//  - 첫 셀(colSpan 3, 앞 3컬럼 지역/부서/등급 병합, left) : toggle()+depthStr() = 그룹 토글 버튼 + 그룹명 (_1/_2 실사용 패턴)
//  - 둘째 셀(점수 컬럼 위치, right) : 선택 메소드(buildExpression) 결과 = 검증 대상. className 'grp_method_cell' 로 태깅해 결정적 실측
scwin.applyGroupby = function (method, soldText) {
    let options = {
        sortIndex: [0, 1],
        sortOrder: [1, 1],
        hideHeader: false,
        hideFooter: true,
        groupbyHeader: [
            { inputType: "expression", expression: "toggle() + depthStr()", colSpan: 3, align: "left", className: "grp_name_cell" },
            { inputType: "expression", expression: scwin.buildExpression(method), align: "right", className: "grp_method_cell" }
        ]
    };
    // showOnlyLastDepth : 미설정('') 이면 옵션 생략(기본값 false), true/false 는 명시
    if (soldText === 'true') {
        options.showOnlyLastDepth = true;
    } else if (soldText === 'false') {
        options.showOnlyLastDepth = false;
    }
    target1.groupby(options);
};



// Group Header Row 들의 '선택 메소드 결과 셀'(둘째 셀, 점수 컬럼 위치)을 DOM(화면) 순서대로 수집
//  - 결과 셀은 className 'grp_method_cell' 로 태깅되어 있어 colSpan 배치와 무관하게 결정적으로 선택
//  - depth 는 td class(w2grid_groupby_depth_N), toggle 아이콘은 span.w2grid_minus/plus 로 확인
scwin.collectGroupHeaderRows = function () {
    let cells = Array.from(document.querySelectorAll("td.grp_method_cell"));
    let rows = [];
    cells.forEach(function (cell) {
        let m = cell.className.match(/w2grid_groupby_depth_(\d+)/);
        let icon = cell.querySelector("span.w2grid_minus, span.w2grid_plus");
        rows.push({
            depth: m ? Number(m[1]) : -1,
            text: (cell.textContent || "").trim(),
            hasIcon: !!icon,
            iconClass: icon ? (icon.className || "") : "(없음)",
            iconMargin: icon ? (icon.style.marginLeft || "") : "(없음)"
        });
    });
    return rows;
};



// [실행] 선택 메소드 expression 적용 및 계산값 확인
scwin.btn_applyMethod_onclick = function () {
    let method = par_method.getValue();
    let soldText = con_showOnlyLastDepth.getText();
    let useLast = (soldText === 'true');

    // 선택 메소드만 groupbyHeader expression 으로 조립하여 재적용
    scwin.applyGroupby(method, soldText);

    let rows = scwin.collectGroupHeaderRows();
    let exp = scwin.expectedArr;

    let lines = [];
    lines.push("[groupby expression 내부메소드 검증] 선택 메소드 = " + method + " / 조립 expression = " + scwin.buildExpression(method) + " / showOnlyLastDepth = " + (soldText === '' ? '미설정(기본 false)' : soldText) + " / Group Header Row 수 = " + rows.length);

    for (let i = 0; i < rows.length; i++) {
        let r = rows[i];
        let e = exp[i] || {};
        // depth 들여쓰기(순수 공백) : depth 당 공백 2칸
        let indent = new Array((e.depth || 0) * 2 + 1).join(' ');
        let prefix = "[" + i + "] " + indent + "(d" + e.depth + ") " + e.name + " -> ";

        if (method === 'toggle') {
            let expMargin = (e.depth * 20) + "px";
            let ok = r.hasIcon && (r.iconMargin === expMargin);
            lines.push(prefix + "toggle : 아이콘=" + r.iconClass + " margin-left=" + r.iconMargin + " (기대 아이콘 존재 + margin-left " + expMargin + ", " + (ok ? "O" : "X") + ")");
        } else if (method === 'depthStr') {
            let expV = useLast ? e.last : e.full;
            let ok = (r.text === expV);
            lines.push(prefix + "depthStr : 실측='" + r.text + "' 기대='" + expV + "' (" + (ok ? "O" : "X") + ")");
        } else {
            // sum/avg/max/min/count/depth : 숫자
            let expV = e[method];
            let readNum = Number(r.text);
            let ok = (readNum === expV);
            lines.push(prefix + method + " : 실측=" + r.text + " 기대=" + expV + " (" + (ok ? "O" : "X") + ")");
        }
    }

    wf_body_bottom.getObj("scwin").setReturnValue(lines.join("\n"));
}
